const N=40,R=6,SG=1.2,S=[[-2.6,0.9],[2.4,-1],[-1.5,-1.3],[2.9,0.6]];
const E=p=>0.5*(p[0]*p[0]+4*p[1]*p[1]);
const G=p=>[p[0],4*p[1]];
const fac=b=>Math.sqrt(Math.max(0,64-b)/(63*b));
function h(n){n=(n^0x9e3779b9)>>>0;n=Math.imul(n^(n>>>16),0x85ebca6b)>>>0;n=Math.imul(n^(n>>>13),0xc2b2ae35)>>>0;return((n^(n>>>16))>>>0)/4294967296}
function gs(seed,s,k,c){const u=Math.max(h(seed*7919+s*104729+k*131+c*17+1),1e-9),v=h(seed*31+s*997+k*7+c*3+12345);return Math.sqrt(-2*Math.log(u))*Math.cos(6.2832*v)}
function noisy(st,inp,seed){const g=G(st.w),f=SG*fac(inp.batchSize);return[g[0]+f*gs(seed,st.s,st.k,0),g[1]+f*gs(seed,st.s,st.k,1)]}
function init(s){return{s,k:0,w:S[s].slice(),f:S[s].slice(),tr:[],ft:[],ep:0,done:false,div:false,fd:false}}
function adv(st,inp,seed){if(st.done)return st;const lr=inp.learningRate,gn=noisy(st,inp,seed),w=[st.w[0]-lr*gn[0],st.w[1]-lr*gn[1]];let f=st.f,ft=st.ft,fd=st.fd;if(!fd){const g=G(f),nf=[f[0]-lr*g[0],f[1]-lr*g[1]];if(E(nf)>R)fd=true;else{ft=ft.concat([f]);f=nf}}const k=st.k+1,div=E(w)>R;return{...st,k,w,f,ft,fd,tr:st.tr.concat([st.w]),ep:st.ep+inp.batchSize/64,div,done:div||k>=N}}
export function initialState(){return init(0)}
export function reduce({state,event,inputs,seed}){if(event.type==='action'){if(event.action==='oneStep')return adv(state,inputs,seed);if(event.action==='newStart')return init((state.s+1)%S.length);return state}if(event.type==='step'&&event.tick%6===0)return adv(state,inputs,seed);return state}
export function evaluate({inputs,state,seed}){const st=state,n={},sf=inputs.showFullPath,P=(p,o)=>[p[0],0.3*E(p)+o,p[1]];
const arr=(g,lr)=>{const dx=-lr*g[0],dz=-lr*g[1],l=Math.hypot(dx,dz),s=0.7071;if(l<1e-6)return{visible:false};return{visible:true,position:P(st.w,0.15),quaternion:[dz/l*s,0,-dx/l*s,s],scale:[1,l,1]}};
n.ball={position:P(st.w,0.15)};n.gball={position:P(st.f,0.1),visible:sf};n.dl={visible:st.div};
for(let i=0;i<N;i++){const a=st.tr[i],b=st.ft[i];n['t'+i]={visible:!!a,position:a?P(a,0.03):[0,0,0]};n['g'+i]={visible:!!b&&sf,position:b?P(b,0.03):[0,0,0]}}
if(st.done){n.an={visible:false};n.ae={visible:false}}else{n.an=arr(noisy(st,inputs,seed),inputs.learningRate);n.ae=arr(G(st.w),inputs.learningRate)}
const e=E(st.w),eb=Math.max(0,e+0.5*fac(inputs.batchSize)*(1+e)*gs(seed,st.s,st.k,2));
return{nodes:n,readouts:{step:st.k,err:e,errBatch:eb,epochs:st.ep}}}

