export function evaluate({inputs,state,seed}){const st=state,n={},sf=inputs.showFullPath,P=(p,o)=>[p[0],0.3*E(p)+o,p[1]];
const arr=(g,lr)=>{const dx=-lr*g[0],dz=-lr*g[1],l=Math.hypot(dx,dz),s=0.7071;if(l<1e-6)return{visible:false};return{visible:true,position:P(st.w,0.4),quaternion:[dz/l*s,0,-dx/l*s,s],scale:[1,3*l,1]}};
const seg=(a,b,v)=>{if(!v||!a||!b)return{visible:false};const A=P(a,0.03),B=P(b,0.03),d=[B[0]-A[0],B[1]-A[1],B[2]-A[2]],l=Math.hypot(d[0],d[1],d[2]);if(l<1e-6)return{visible:false};const x=d[2]/l,y=1+d[1]/l,z=-d[0]/l,m=Math.hypot(x,y,z);if(m<1e-6)return{visible:true,position:[(A[0]+B[0])/2,(A[1]+B[1])/2,(A[2]+B[2])/2],quaternion:[1,0,0,0],scale:[1,l,1]};return{visible:true,position:[(A[0]+B[0])/2,(A[1]+B[1])/2,(A[2]+B[2])/2],quaternion:[x/m,0,z/m,y/m],scale:[1,l,1]}};
