const e=E(st.w),eb=Math.max(0,e+0.5*fac(inputs.batchSize)*(1+e)*gs(seed,st.s,st.k,2));
return{nodes:n,readouts:{step:st.k,err:e,errBatch:eb,epochs:st.ep}}}

